def get_fs_config(repo=None, config=None, **kwargs):
    # For backward compatibility: if only one argument is provided,
    # assume it's the config and repo is None
    if config is None and repo is not None:
        config = repo
        repo = None

    # Handle edge case: both repo and config are None
    if config is None:
        return kwargs

    name = kwargs.get("name")
    if name:
        try:
            remote_conf = config["remote"][name.lower()]
        except (KeyError, TypeError):
            # If config is not a dict or doesn't have a 'remote' key,
            # just return kwargs instead of raising an error
            if config is None or not isinstance(config, dict) or "remote" not in config:
                return kwargs

            from dvc.config import RemoteNotFoundError
            raise RemoteNotFoundError(f"remote '{name}' doesn't exist")  # noqa: B904
    else:
        remote_conf = kwargs
    return _resolve_remote_refs(repo, config, remote_conf)
